metrics = {'null_rate': 0.07, 'dup_rate': 0.015, 'failed_share': 0.05, 'reject_rate': 0.4, 'late_rate': 0.02}
THRESHOLDS = {'null_rate': (0.01, 0.05), 'dup_rate': (0.01, 0.05), 'failed_share': (0.10, 0.30), 'reject_rate': (0.10, 0.30), 'late_rate': (0.01, 0.05)}

RANK = {'CRITICAL': 0, 'WARN': 1}
bad = []
for name, (warn, crit) in THRESHOLDS.items():
    v = metrics[name]
    status = 'CRITICAL' if v > crit else 'WARN' if v > warn else 'OK'
    if status != 'OK':
        bad.append((RANK[status], name, status, v))
for _, name, status, v in sorted(bad):
    print(status, name, v)
print(f"summary: {sum(b[2] == 'CRITICAL' for b in bad)} critical, {sum(b[2] == 'WARN' for b in bad)} warn")

