WITH t AS (
  SELECT run_date, value,
         ROUND(AVG(value) OVER (ORDER BY run_date ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), 4) AS previous_avg
  FROM quality_run
  WHERE metric = 'null_rate'
)
SELECT run_date, value, previous_avg
FROM t
WHERE previous_avg IS NOT NULL AND value > 1.5 * previous_avg
ORDER BY run_date;

history = [
    {'a': 'OK', 'b': 'WARN', 'c': 'OK'},
    {'a': 'WARN', 'b': 'WARN', 'c': 'OK'},
    {'a': 'WARN', 'b': 'WARN', 'c': 'OK'},
    {'a': 'CRITICAL', 'b': 'OK', 'c': 'OK'},
]

RANK = {'OK': 0, 'WARN': 1, 'CRITICAL': 2}
for i in range(1, len(history)):
    lines = []
    for m in sorted(history[i]):
        before, now = history[i - 1][m], history[i][m]
        if RANK[now] > RANK[before]:
            lines.append(f'run {i}: {m} {before} -> {now}')
        elif RANK[now] < RANK[before]:
            lines.append(f'run {i}: {m} recovered')
    print('\n'.join(lines) if lines else f'run {i}: no alerts')
